/* Host harness for native/open-gate/og_mem.c, included unchanged, with fake syscalls, DMA and CP memory.
 *
 * The DMA buffer is one page followed by a PROT_NONE guard page, so a read or write past it faults (and ASan sees
 * any other overrun). Prints "ok <name>" per check and exits nonzero on the first failure.
 * Needs og_config.h, og_sites (the site image) and og_mem_seed.h (stored_record.json's offsets and stock bytes),
 * generated by tests/test_open_gate.py.
 */
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/mman.h>
#include "og_config.h"

#define OG_SYS_H
#define OG_O_RDONLY 0
#define OG_O_RDWR 2
#define OG_O_SYNC 0
#define OG_O_CLOEXEC 0
enum { FD_MEM = 10, FD_MAPS = 12 };
static const char *maps_text;
static unsigned maps_at;
static long og_openat(const char *p, long f, long m)
{
    (void)f; (void)m;
    if (!strcmp(p, "/proc/self/maps")) { maps_at = 0; return FD_MAPS; }
    return FD_MEM;
}
static long og_close(long fd) { (void)fd; return 0; }
static long og_read(long fd, void *d, unsigned long n)
{
    if (fd != FD_MAPS) return -1;
    unsigned long left = strlen(maps_text) - maps_at, k = left < n ? left : n;
    memcpy(d, maps_text + maps_at, k);
    maps_at += (unsigned)k;
    return (long)k;
}
static long og_pread(long fd, void *d, unsigned long n, uint64_t at) { (void)fd; (void)at; memset(d, 0, n); return (long)n; }
static long og_pwrite(long fd, const void *s, unsigned long n, uint64_t at) { (void)fd; (void)s; (void)at; return (long)n; }
#define PHYS (OG_DMM_PHYS_MIN + 0x10000ull)
static uint8_t *dmabuf, *avcam_buf;
static void *og_mmap(unsigned long len, long fd, uint64_t off) { (void)fd; (void)len; return off == PHYS ? dmabuf : avcam_buf; }
static void og_munmap(void *a, unsigned long l) { (void)a; (void)l; }

#include "og_mem.c"
#include "og_mem_seed.h"

#define CP_BYTES 0x2000000u
static uint8_t *cp;
static uint64_t fake_alloc(uint32_t n, uint32_t *h) { (void)n; *h = 1; return PHYS; }
static void fake_free(uint32_t h) { (void)h; }
static int fake_dma(int dir, uint64_t src, uint64_t dst, uint32_t n)
{
    uint64_t cp_at = dir == 0 ? src : dst, phys = dir == 0 ? dst : src;
    if (cp_at + n > CP_BYTES || phys < PHYS || phys + n > PHYS + 0x1000) {
        printf("FAIL dma out of range: dir %d cp %#llx phys %#llx n %u\n", dir, (unsigned long long)cp_at,
               (unsigned long long)phys, n);
        exit(1);
    }
    if (dir == 0) memcpy(dmabuf + (phys - PHYS), cp + cp_at, n);
    else memcpy(cp + cp_at, dmabuf + (phys - PHYS), n);
    return 0;
}
void *dlsym(void *l, const char *name)
{
    (void)l;
    if (!strcmp(name, OG_SYM_DMM_ALLOC)) return (void *)fake_alloc;
    if (!strcmp(name, OG_SYM_DMM_FREE)) return (void *)fake_free;
    if (!strcmp(name, OG_SYM_DMA)) return (void *)fake_dma;
    return 0;
}

static void check(int ok, const char *name)
{
    if (!ok) { printf("FAIL %s\n", name); exit(1); }
    printf("ok %s\n", name);
}

static void put32(uint32_t va, uint32_t v) { memcpy(cp + va, &v, 4); }

/* The 0x12b9cc0 chain with P, Q, the mode list and the records at the given CP addresses. Record 0 is drive mode
 * `first` and record 1 drive mode `second`; `stock_family` (0 NTSC, 1 PAL) has its stock bytes in the record of its
 * drive mode. */
static void chain(uint32_t p, uint32_t q, uint32_t list, uint32_t records, uint32_t first, uint32_t second,
                  int stock_family)
{
    memset(cp, 0x5a, CP_BYTES);
    put32(OG_RECORD_ROOT + OG_RECORD_P_FIELD, p);
    put32(p + OG_RECORD_Q_FIELD, q);
    put32(q + OG_RECORD_COUNT_FIELD, 2);
    put32(q + OG_RECORD_LIST_FIELD, list);
    put32(q + OG_RECORD_RECORDS_FIELD, records);
    put32(list, first);
    put32(list + 4, second);
    uint32_t mode = stock_family ? OG_DRIVE_MODE_PAL : OG_DRIVE_MODE_NTSC;
    uint32_t at = records + (mode == first ? 0 : OG_RECORD_BYTES);
    const uint8_t *old = stock_family ? seed_pal_old : seed_ntsc_old;
    for (unsigned i = 0; i < sizeof seed_off / sizeof *seed_off; i++) cp[at + seed_off[i]] = old[i];
}

static void detect_case(const char *name, uint32_t p, uint32_t q, uint32_t list, uint32_t records, uint32_t first,
                        uint32_t second, int family)
{
    chain(p, q, list, records, first, second, family);
    og_mem *m;
    og_family f = 9;
    og_status s = og_mem_begin(&m, &f);
    uint32_t mode = family ? OG_DRIVE_MODE_PAL : OG_DRIVE_MODE_NTSC;
    uint32_t want = records + (mode == first ? 0 : OG_RECORD_BYTES);
    check(s == OG_OK && f == (og_family)family && m->record == want, name);
    og_mem_end(m);
}

/* The camera's own list (cpapp-b.bin CP 0xc98330: 0x880 at index 9, 0x8c0 at index 10), both records holding the kit's
 * stock bytes for their mode except `bad_byte` at record offset 0xb8 of the record of drive mode `bad_mode` (0: none).
 * An NTSC camera's trace (diagnostic build 8ba24f9) showed 0x8c0's record as the kit's NTSC stock and 0x880's as the
 * kit's PAL stock but e5 for 98 at 0xb8; the kit read 98 there on a camera set to PAL. */
static og_status camera_case(uint32_t bad_mode, uint8_t bad_byte, og_family *f, uint32_t *record)
{
    static const uint32_t modes[30] = {0x5000, 0x5200, 0xc100, 0x5400, 0xc000, 0x5002, 0x5020, 0xa000,
                                       0xa100, 0x880,  0x8c0,  0xae0,  0xb20,  0xbc0,  0x5001, 0x5201,
                                       0x5401, 0xc010, 0xc110, 0x5004, 0x5021, 0xa030, 0xa130, 0x821,
                                       0x8c1,  0xae1,  0xb21,  0xbc1,  0x8000, 0xe000};
    const uint32_t p = 0x12ba16c, q = 0x12ba7f8, list = 0xc98330, records = 0x1fd1224;   /* as the camera reported */
    memset(cp, 0x5a, CP_BYTES);
    put32(OG_RECORD_ROOT + OG_RECORD_P_FIELD, p);
    put32(p + OG_RECORD_Q_FIELD, q);
    put32(q + OG_RECORD_COUNT_FIELD, 30);
    put32(q + OG_RECORD_LIST_FIELD, list);
    put32(q + OG_RECORD_RECORDS_FIELD, records);
    for (uint32_t i = 0; i < 30; i++) {
        put32(list + 4 * i, modes[i]);
        const uint8_t *old = modes[i] == OG_DRIVE_MODE_NTSC ? seed_ntsc_old
                             : modes[i] == OG_DRIVE_MODE_PAL ? seed_pal_old : 0;
        for (unsigned k = 0; old && k < sizeof seed_off / sizeof *seed_off; k++)
            cp[records + OG_RECORD_BYTES * i + seed_off[k]] = old[k];
        if (bad_mode && modes[i] == bad_mode) cp[records + OG_RECORD_BYTES * i + 0xb8] = bad_byte;
    }
    og_mem *m;
    *f = 9;
    og_status s = og_mem_begin(&m, f);
    *record = m ? m->record : 0;
    og_mem_end(m);
    return s;
}

static og_mem *opened(void)
{
    og_mem *m = &the_mem;
    m->open = 1;
    m->sync_fd = m->mem_fd = m->self_fd = -1;
    check(open_all(m) == OG_OK, "open_all");
    return m;
}

int main(void)
{
    setvbuf(stdout, 0, _IONBF, 0);
    cp = malloc(CP_BYTES);
    dmabuf = mmap(0, 0x2000, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANON, -1, 0);
    mprotect(dmabuf + 0x1000, 0x1000, PROT_NONE);
    avcam_buf = calloc(1, OG_AVCAM_MAP_BYTES);
    maps_text = "7f00000000-7f00100000 r-xp 00000000 00:00 0 /usr/lib/libmpr.so\n";

    /* The pointer chain, each link below and above the page the previous read left cached, for both families. */
    detect_case("detect ntsc, chain descending", 0x1200000, 0x1100000, 0x1000000, 0x900000, OG_DRIVE_MODE_NTSC,
                OG_DRIVE_MODE_PAL, 0);
    detect_case("detect ntsc, chain ascending", 0x1400000, 0x1500000, 0x1600000, 0x1700000, OG_DRIVE_MODE_NTSC,
                OG_DRIVE_MODE_PAL, 0);
    detect_case("detect pal, chain ascending", 0x1400000, 0x1500000, 0x1600000, 0x1700000, OG_DRIVE_MODE_NTSC,
                OG_DRIVE_MODE_PAL, 1);
    detect_case("detect pal, records in reverse order", 0x1400000, 0x1500000, 0x1600000, 0x1700000,
                OG_DRIVE_MODE_PAL, OG_DRIVE_MODE_NTSC, 1);

    {
        og_family f;
        uint32_t record;
        check(camera_case(OG_DRIVE_MODE_PAL, 0xe5, &f, &record) == OG_OK && f == OG_FAMILY_NTSC &&
                  record == 0x1fd1224 + OG_RECORD_BYTES * 10,
              "the NTSC camera's records: NTSC, the record of 0x8c0 at index 10");
        check(camera_case(OG_DRIVE_MODE_NTSC, 0xe5, &f, &record) == OG_OK && f == OG_FAMILY_PAL &&
                  record == 0x1fd1224 + OG_RECORD_BYTES * 9,
              "the mirror case: PAL, the record of 0x880 at index 9");
        check(camera_case(0, 0, &f, &record) == OG_FOREIGN && record == 0, "both records stock: ambiguous, refused");
    }

    og_mem *m = opened();
    uint8_t b[16], src[8] = {1, 2, 3, 4, 5, 6, 7, 8};
    memset(cp, 0, CP_BYTES);
    cp[0x200000] = 0x11;
    cp[0x201100] = 0x22;
    cp[0x1ff000] = 0x33;
    check(og_mem_read(m, OG_CP, 0x200000, b, 1) == OG_OK && b[0] == 0x11, "read fills the cache");
    check(og_mem_read(m, OG_CP, 0x201100, b, 1) == OG_OK && b[0] == 0x22, "read above the cached page");
    check(og_mem_read(m, OG_CP, 0x1ff000, b, 1) == OG_OK && b[0] == 0x33, "read below the cached page");
    for (unsigned i = 0; i < 16; i++) cp[0x202ff8 + i] = (uint8_t)(0x40 + i);
    check(og_mem_read(m, OG_CP, 0x202ff8, b, 16) == OG_OK && b[0] == 0x40 && b[15] == 0x4f, "read across a page");
    check(og_mem_write(m, OG_CP, 0x203ffc, src, 8) == OG_OK && cp[0x203ffc] == 1 && cp[0x204003] == 8 &&
              cp[0x203ffb] == 0 && cp[0x204004] == 0,
          "write across a page keeps its neighbours");
    cp[0x300010] = 0x77;
    check(og_mem_read(m, OG_CP, 0x300000, b, 1) == OG_OK && og_mem_write(m, OG_CP, 0x305000, src, 4) == OG_OK &&
              cp[0x305000] == 1 && cp[0x305003] == 4 && og_mem_read(m, OG_CP, 0x300010, b, 1) == OG_OK && b[0] == 0x77,
          "write above the cached page, then read the first page again");
    check(og_mem_read(m, OG_CP, OG_CP_VA_END - 2u, b, 4) == OG_IO, "read past the CP range is refused");
    og_mem_end(m);

    /* /proc/self/maps: only libmpr.so's offset-0 readable mapping counts. */
    process.mpr = process.mpr_end = 0;
    maps_text = "7e00000000-7e00010000 r--p 00010000 00:00 0 /usr/lib/libmpr.so\n"
                "7f00000000-7f00100000 r-xp 00000000 00:00 0 /usr/lib/libmpr.so\n";
    find_libmpr();
    check(process.mpr == 0x7f00000000ull && process.mpr_end == 0x7f00100000ull, "libmpr base from its offset-0 line");
    process.mpr = process.mpr_end = 0;
    maps_text = "7f00000000-7f00100000 r-xp 00000000 00:00 0 /usr/lib/libmpr.so.bak\n";
    find_libmpr();
    check(process.mpr == 0, "other paths ignored");
    return 0;
}
